1	export interface Scenario {
2	  customer: { yearsWithMHPCO: number };
3	  steps: Step[];
4	}
5	
6	export type Step = QuoteStep | ClaimStep;
7	
8	export interface QuoteStep {
9	  op: "quote";
10	  items: Item[];
11	}
12	
13	export interface Item {
14	  type: string;
15	  material?: string;
16	  enchantment?: number;
17	  cursed?: boolean;
18	}
19	
20	export interface ClaimStep {
21	  op: "claim";
22	  policy: number;
23	  incident: Incident;
24	}
25	
26	export interface Incident {
27	  cause: string;
28	  damages: Damage[];
29	}
30	
31	export interface Damage {
32	  itemType: string;
33	  amount: number;
34	}
35	
36	export type Result = { premium: number } | { payout: number; remainingCap: number };
37	
38	const PROCESSING_FEE = 5;
39	
40	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
41	
42	/** Rounds up in the MHPCO's favor, ignoring binary floating-point noise. */
43	const roundPremium = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
44	
45	/** The closed set of insurable item types, each with its base premium in gold. */
46	const BASE_PREMIUMS = {
47	  sword: 100,
48	  amulet: 60,
49	  staff: 80,
50	  potion: 40,
51	  rune: 25,
52	  moonstone: 25,
53	} as const satisfies Record<string, number>;
54	
55	export type ItemType = keyof typeof BASE_PREMIUMS;
56	
57	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type as ItemType];
58	
59	const BLOCK_SIZE = 3;
60	const BLOCK_BASE_PREMIUM = 60;
61	
62	const isBlock = (items: Item[]): boolean =>
63	  items.length === BLOCK_SIZE && items.every((item) => item.type === items[0].type);
64	
65	/** Three alike components form a block, priced at a special base premium. */
66	const blockAwareBasePremium = (items: Item[]): number =>
67	  isBlock(items)
68	    ? BLOCK_BASE_PREMIUM
69	    : items.reduce((sum, item) => sum + basePremiumOf(item), 0);
70	
71	const quotePremium = (items: Item[]): number => {
72	  const basePremium = blockAwareBasePremium(items);
73	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
74	  return roundPremium(basePremium + firstInsuranceSurcharge + PROCESSING_FEE);
75	};
76	
77	const runStep = (step: Step): Result => {
78	  if (step.op === "quote") return { premium: quotePremium(step.items) };
79	  throw new Error(`Unsupported step: ${step.op}`);
80	};
81	
82	export const runScenario = (scenario: Scenario): { results: Result[] } => {
83	  return { results: scenario.steps.map(runStep) };
84	};
